184	    async fn search(
185	        &self,
186	        request: SearchMemoriesRequest,
187	    ) -> Result<SearchMemoriesResponse, MemoriesBackendError> {
188	        let query = request.query.trim();
189	        if query.is_empty() {
190	            return Err(MemoriesBackendError::EmptyQuery);
191	        }
192	
193	        let max_results = request.max_results.min(MAX_SEARCH_RESULTS);
194	        let start = self.resolve_scoped_path(request.path.as_deref())?;
195	        let start_index = match request.cursor.as_deref() {
196	            Some(cursor) => cursor.parse::<usize>().map_err(|_| {
197	                MemoriesBackendError::invalid_cursor(cursor, "must be a non-negative integer")
198	            })?,
199	            None => 0,
200	        };
201	        let Some(metadata) = Self::metadata_or_none(&start).await? else {
202	            return Ok(SearchMemoriesResponse {
203	                query: request.query,
204	                path: request.path,
205	                matches: Vec::new(),
206	                next_cursor: None,
207	                truncated: false,
208	            });
209	        };
210	        reject_symlink(&display_relative_path(&self.root, &start), &metadata)?;
211	
212	        let mut matches = Vec::new();
213	        search_entries(&self.root, &start, &metadata, query, &mut matches).await?;
214	        matches.sort_by(|left, right| {
215	            left.path
216	                .cmp(&right.path)
217	                .then(left.line_number.cmp(&right.line_number))
218	        });
219	        if start_index > matches.len() {
220	            return Err(MemoriesBackendError::invalid_cursor(
221	                start_index.to_string(),
222	                "exceeds result count",
223	            ));
224	        }
225	        let end_index = start_index.saturating_add(max_results).min(matches.len());
226	        let next_cursor = (end_index < matches.len()).then(|| end_index.to_string());
227	        let truncated = next_cursor.is_some();
228	        Ok(SearchMemoriesResponse {
229	            query: request.query,
230	            path: request.path,
231	            matches: matches.drain(start_index..end_index).collect(),
232	            next_cursor,
233	            truncated,
234	        })
235	    }
236	}
