238	async fn search_entries(
239	    root: &Path,
240	    current: &Path,
241	    current_metadata: &std::fs::Metadata,
242	    query: &str,
243	    matches: &mut Vec<MemorySearchMatch>,
244	) -> Result<(), MemoriesBackendError> {
245	    if current_metadata.is_file() {
246	        search_file(root, current, query, matches).await?;
247	        return Ok(());
248	    }
249	    if !current_metadata.is_dir() {
250	        return Ok(());
251	    }
252	
253	    let mut pending = vec![current.to_path_buf()];
254	    while let Some(dir_path) = pending.pop() {
255	        for path in read_sorted_dir_paths(&dir_path).await? {
256	            let Some(metadata) = LocalMemoriesBackend::metadata_or_none(&path).await? else {
257	                continue;
258	            };
259	            if metadata.file_type().is_symlink() {
260	                continue;
261	            }
262	            if metadata.is_dir() {
263	                pending.push(path);
264	            } else if metadata.is_file() {
265	                search_file(root, &path, query, matches).await?;
266	            }
267	        }
268	    }
269	
270	    Ok(())
271	}
272	
273	async fn search_file(
274	    root: &Path,
275	    path: &Path,
276	    query: &str,
277	    matches: &mut Vec<MemorySearchMatch>,
278	) -> Result<(), MemoriesBackendError> {
279	    let content = match tokio::fs::read_to_string(path).await {
280	        Ok(content) => content,
281	        Err(err) if err.kind() == std::io::ErrorKind::InvalidData => return Ok(()),
282	        Err(err) => return Err(err.into()),
283	    };
284	    for (idx, line) in content.lines().enumerate() {
285	        if line.contains(query) {
286	            matches.push(MemorySearchMatch {
287	                path: display_relative_path(root, path),
288	                line_number: idx + 1,
289	                line: line.to_string(),
290	            });
291	        }
292	    }
293	    Ok(())
294	}
295	
296	async fn read_sorted_dir_paths(dir_path: &Path) -> Result<Vec<PathBuf>, MemoriesBackendError> {
297	    let mut dir = match tokio::fs::read_dir(dir_path).await {
298	        Ok(dir) => dir,
299	        Err(err) if err.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
300	        Err(err) => return Err(err.into()),
301	    };
302	    let mut paths = Vec::new();
303	    while let Some(entry) = dir.next_entry().await? {
304	        paths.push(entry.path());
305	    }
306	    paths.sort();
307	    Ok(paths)
308	}
